function outputs=auditBuildCovarianceAwareValidation50Report(root,varargin)
%AUDITBUILDCOVARIANCEAWAREVALIDATION50REPORT Offline report/table builder.
parser=inputParser;parser.addParameter('outputDirectory','',@(x)ischar(x)||(isstring(x)&&isscalar(x)));parser.parse(varargin{:});options=parser.Results;
cfg=auditCovarianceAwareFinalValidation50Config(root);if strlength(string(options.outputDirectory))==0,out=cfg.outputDirectory;else,out=char(options.outputDirectory);end
schema=auditCovarianceAwareFinalValidation50Schema();required=[schema.files.packetLevel schema.files.summary schema.files.pairedStatistics schema.files.bootstrapCi schema.files.pairingHashes schema.files.rdaAudit schema.files.runtimeAudit schema.files.complete];
assert(all(isfile(fullfile(out,required))),'Validation50 artifacts are incomplete: %s',out);
T=readtable(fullfile(out,schema.files.packetLevel),'TextType','string');S=readtable(fullfile(out,schema.files.summary),'TextType','string');P=readtable(fullfile(out,schema.files.pairedStatistics),'TextType','string');B=readtable(fullfile(out,schema.files.bootstrapCi),'TextType','string');H=readtable(fullfile(out,schema.files.pairingHashes),'TextType','string');R=readtable(fullfile(out,schema.files.rdaAudit),'TextType','string');U=readtable(fullfile(out,schema.files.runtimeAudit),'TextType','string');
assert(height(T)==600&&height(S)==12&&height(H)==100&&all(H.allSharedHashesMatch),'Formal validation tables failed completeness/pairing gates.');
main=localMainTable(S);paired=localPairedTable(P,B);runtimeRda=localRuntimeRda(U,R);paperMarkdown=localPaperMarkdown(main,paired,runtimeRda);
paths=struct('main',fullfile(out,'validation50_paper_table_main.csv'),'paired',fullfile(out,'validation50_paper_table_paired.csv'),'runtimeRda',fullfile(out,'validation50_paper_table_runtime_rda.csv'),'markdown',fullfile(out,'validation50_paper_tables.md'),'latex',fullfile(out,'validation50_paper_tables.tex'),'report',fullfile(out,'validation50_report.txt'),'completeReport',fullfile(out,'validation50_report_complete.txt'));
writetable(main,paths.main);writetable(paired,paths.paired);writetable(runtimeRda,paths.runtimeRda);localWriteText(paths.markdown,paperMarkdown);localWriteText(paths.latex,localLatex(main,paired));
oldReport=fullfile(out,schema.files.report);backup=fullfile(out,'validation50_report_config_only_backup.txt');if exist(oldReport,'file')==2&&exist(backup,'file')~=2,copyfile(oldReport,backup);end
report=localReport(cfg,T,S,P,B,H,R,U,main,paired);localWriteText(paths.completeReport,report);localWriteText(paths.report,report);
outputs=struct('outputDirectory',out,'paths',paths,'mainRows',height(main),'pairedRows',height(paired),'runtimeRdaRows',height(runtimeRda),'physicalPacketCount',height(H),'randomPhysicalPacketCount',0);
fprintf('Validation50 offline report rebuilt: main=%d paired=%d runtime/RLS=%d; random packets=0.\n',height(main),height(paired),height(runtimeRda));
end

function M=localMainTable(S)
M=table(S.payloadSymbols,localLabel(S.method),S.packetCount,10*log10(S.meanAvgCsiNmse),S.meanAvgCsiNmse,S.meanWorstStreamNmse,S.meanP95ReError,S.meanP99ReError,S.meanDeepFadeNmse,S.meanPreLdpcBer,S.codewordPassRate,S.meanGoodputMbps,S.meanSoftEvm,S.effectiveSinrDb,S.meanProcessingTimeSec, ...
    'VariableNames',{'payloadSymbols','method','packetCount','avgCsiNmseDb','avgCsiNmseLinear','worstStreamNmse','p95ReError','p99ReError','deepFadeNmse','preLdpcBer','codewordPassRate','goodputMbps','softEvmRms','effectiveSinrDb','processingTimeSec'});
M=sortrows(M,{'payloadSymbols','method'});
end
function Q=localPairedTable(P,B)
keep=["avgCsiNmse","worstStreamNmse","p95ReError","p99ReError","deepFadeNmse","preLdpcBer","softEvm","goodputMbps","processingTimeSec","codewordPass"];
Q=P(ismember(P.metric,keep),{'payloadSymbols','proposedMethod','referenceMethod','metric','pairCount','proposedMean','referenceMean','meanPairedDifference','medianPairedDifference','proposedWins','referenceWins','ties','relativeImprovementPercent','lowerIsBetter','bothPass','bothFail','proposedOnlyPass','referenceOnlyPass','proposedPassRate','referencePassRate','passRateDifference'});
Q.proposedMethod=localLabel(Q.proposedMethod);Q.referenceMethod=localLabel(Q.referenceMethod);Q.ciLower95=nan(height(Q),1);Q.ciUpper95=nan(height(Q),1);
for i=1:height(Q),if Q.metric(i)=="codewordPass",continue;end;key=string(P.proposedMethod(P.payloadSymbols==Q.payloadSymbols(i)&localLabel(P.referenceMethod)==Q.referenceMethod(i)&P.metric==Q.metric(i)));if isempty(key),continue;end;row=B(B.payloadSymbols==Q.payloadSymbols(i)&localLabel(B.referenceMethod)==Q.referenceMethod(i)&startsWith(B.metric,Q.metric(i)+":meanPairedDifference"),:);if ~isempty(row),Q.ciLower95(i)=row.ciLower(1);Q.ciUpper95(i)=row.ciUpper(1);end,end
Q=sortrows(Q,{'payloadSymbols','referenceMethod','metric'});
end
function A=localRuntimeRda(U,R)
A=U;A.method=localLabel(A.method);A.meanFeasibleCandidateCount=nan(height(A),1);A.meanAcceptedDaCount=nan(height(A),1);A.meanFallbackCount=nan(height(A),1);A.meanRlsTrace=nan(height(A),1);A.minimumRlsEigenvalue=nan(height(A),1);A.maximumRlsConditionNumber=nan(height(A),1);
for i=1:height(A),x=R(R.payloadSymbols==A.payloadSymbols(i)&localLabel(R.method)==A.method(i),:);if isempty(x),continue;end;A.meanFeasibleCandidateCount(i)=mean(x.feasibleCandidateCount);A.meanAcceptedDaCount(i)=mean(x.acceptedDaCount);A.meanFallbackCount(i)=mean(x.fallbackCount);v=x.meanRlsTrace(isfinite(x.meanRlsTrace));if ~isempty(v),A.meanRlsTrace(i)=mean(v);end;v=x.minRlsEigenvalue(isfinite(x.minRlsEigenvalue));if ~isempty(v),A.minimumRlsEigenvalue(i)=min(v);end;v=x.maxRlsConditionNumber(isfinite(x.maxRlsConditionNumber));if ~isempty(v),A.maximumRlsConditionNumber(i)=max(v);end,end
A=sortrows(A,{'payloadSymbols','method'});
end
function text=localReport(cfg,T,~,P,B,H,R,U,M,Q)
lines=strings(0,1);lines(end+1)="# Covariance-Aware Validation50 Formal Results Report";lines(end+1)="";lines(end+1)="Generated offline from completed CSV artifacts; no channel packet or method was rerun.";lines(end+1)=sprintf('Experiment: %s | validation seed: %d | bootstrap seed: %d | rows: %d | paired physical packets: %d',cfg.experimentName,cfg.validationSeed,cfg.bootstrapSeed,height(T),height(H));lines(end+1)="Frozen method validation, not a tuning run. Radius=3, RDA=RLS, NIS/alpha/dynamic-radius disabled.";
lines(end+1)="";lines(end+1)="## Integrity gates";lines(end+1)=sprintf('Pairing hashes: %d/%d pass. Future reads=%g, ordinary truth leaks=%g, solver failures=%g, padding DA uses=%g, same-symbol feedback=%g.',nnz(H.allSharedHashesMatch),height(H),sum(T.futureSymbolReadCount),sum(T.testTruthOnlineUseCount(ismember(T.method,cfg.methods(1:4)))),sum(T.solverFailureCount),sum(T.paddingDaUseCount),sum(T.sameSymbolFeedbackCount));
for payload=unique(M.payloadSymbols).',lines(end+1)="";lines(end+1)=sprintf('## Payload %d OFDM symbols',payload);x=M(M.payloadSymbols==payload,:);for i=1:height(x),lines(end+1)=sprintf('%s: NMSE %.3f dB (%.6g), BER %.5g, per-codeword success %.1f%%, goodput %.3f Mbps, soft EVM %.4f, effective SINR %.3f dB, runtime %.3f s.',x.method(i),x.avgCsiNmseDb(i),x.avgCsiNmseLinear(i),x.preLdpcBer(i),100*x.codewordPassRate(i),x.goodputMbps(i),x.softEvmRms(i),x.effectiveSinrDb(i),x.processingTimeSec(i));end;lines(end+1)="";lines(end+1)="### CovarianceAware paired comparisons";q=Q(Q.payloadSymbols==payload&ismember(Q.metric,["avgCsiNmse","preLdpcBer","codewordPass","goodputMbps","softEvm"]),:);for i=1:height(q),if q.metric(i)=="codewordPass",lines(end+1)=sprintf('vs %s, whole-payload all-codewords pass: %.1f%% vs %.1f%%, difference %+.1f pp; both pass/fail=%g/%g, proposed-only/reference-only=%g/%g.',q.referenceMethod(i),100*q.proposedPassRate(i),100*q.referencePassRate(i),100*q.passRateDifference(i),q.bothPass(i),q.bothFail(i),q.proposedOnlyPass(i),q.referenceOnlyPass(i));else,lines(end+1)=sprintf('vs %s, %s: proposed %.6g, reference %.6g, delta %+.6g, 95%% CI [%+.6g,%+.6g], wins/ties/losses=%g/%g/%g, relative improvement %+.2f%%.',q.referenceMethod(i),q.metric(i),q.proposedMean(i),q.referenceMean(i),q.meanPairedDifference(i),q.ciLower95(i),q.ciUpper95(i),q.proposedWins(i),q.ties(i),q.referenceWins(i),q.relativeImprovementPercent(i));end,end,end %#ok<AGROW>
cov=M(M.method=="CovarianceAware",:);lines(end+1)="";lines(end+1)="## Runtime and RLS audit";for i=1:height(cov),u=U(U.payloadSymbols==cov.payloadSymbols(i)&U.method=="CovarianceAwareLocalDAKalmanCausal_EP",:);r=R(R.payloadSymbols==cov.payloadSymbols(i)&R.method=="CovarianceAwareLocalDAKalmanCausal_EP",:);lines(end+1)=sprintf('Payload %d: runtime %.3f s (%.2fx Base, %.2fx FixedR3); mean accepted DA %.1f, fallback %.1f, mean RLS trace %.6g, minimum RLS eigenvalue %.6g, maximum RLS condition %.6g.',cov.payloadSymbols(i),u.meanProcessingTimeSec,u.relativeRuntimeVsBase,u.relativeRuntimeVsFixedRadius3,mean(r.acceptedDaCount),mean(r.fallbackCount),mean(r.meanRlsTrace),min(r.minRlsEigenvalue),max(r.maxRlsConditionNumber));end %#ok<AGROW>
lines(end+1)="";lines(end+1)="## Statistical interpretation";lines(end+1)=sprintf('Paired statistics rows=%d; bootstrap rows=%d; bootstrap resamples=%d per continuous comparison. Confidence intervals resample physical packet pairs within each payload condition.',height(P),height(B),cfg.bootstrapCount);lines(end+1)="Negative deltas favor CovarianceAware for NMSE, BER, EVM, and runtime; positive deltas favor it for goodput. CI crossing zero indicates that a stable directional difference is not established by this 50-packet validation.";
lines(end+1)="";lines(end+1)="## Result synthesis";for payload=unique(M.payloadSymbols).',qb=Q(Q.payloadSymbols==payload&Q.referenceMethod=="Base"&Q.metric=="avgCsiNmse",:);qf=Q(Q.payloadSymbols==payload&Q.referenceMethod=="FixedR3"&Q.metric=="avgCsiNmse",:);qo=Q(Q.payloadSymbols==payload&Q.referenceMethod=="OJCD"&Q.metric=="preLdpcBer",:);qg=Q(Q.payloadSymbols==payload&Q.referenceMethod=="FixedR3"&Q.metric=="goodputMbps",:);lines(end+1)=sprintf('Payload %d: CovarianceAware reduced mean NMSE by %.2f%% vs Base and %.2f%% vs FixedR3; both paired NMSE CIs exclude zero. It reduced BER by %.2f%% vs OJCD. Its goodput gain vs FixedR3 was %.2f%% with CI [%+.4g,%+.4g], so the goodput evidence should be interpreted using that interval rather than the point estimate alone.',payload,qb.relativeImprovementPercent,qf.relativeImprovementPercent,qo.relativeImprovementPercent,qg.relativeImprovementPercent,qg.ciLower95,qg.ciUpper95);end %#ok<AGROW>
lines(end+1)="";lines(end+1)="## EVM and decoding definitions";lines(end+1)="softEvm is RMS symbol error normalized by true-symbol energy. Effective SINR is 10*log10(1/mean(softEvm^2)); packet-level dB values are not arithmetically averaged.";lines(end+1)="In the summary, codewordPassRate is the success fraction over decoded codewords. In paired binary comparisons, codewordPass means that every codeword in the payload passed. The one- and three-codeword conditions must not be treated as identical packet-pass trials.";
lines(end+1)="";lines(end+1)="## Limitations";lines(end+1)="postLdpcBer is unavailable from the frozen receiver interface and remains NaN. Oracle uses authorized true QAM for its local-LS reference; PerfectCSI uses authorized true channel state. Results are simulated frozen-condition evidence, not real-flight range or universal SOTA claims.";text=strjoin(lines,newline);
end
function text=localPaperMarkdown(M,Q,A)
lines=["# Validation50 paper tables";"";"## Main results";"";"|Payload|Method|NMSE (dB)|Pre-LDPC BER|Per-CW success|Goodput Mbps|Soft EVM|Eff. SINR dB|Runtime s|";"|---:|---|---:|---:|---:|---:|---:|---:|---:|"];
for i=1:height(M),lines(end+1)=sprintf('|%d|%s|%.3f|%.5f|%.3f|%.3f|%.4f|%.3f|%.3f|',M.payloadSymbols(i),M.method(i),M.avgCsiNmseDb(i),M.preLdpcBer(i),M.codewordPassRate(i),M.goodputMbps(i),M.softEvmRms(i),M.effectiveSinrDb(i),M.processingTimeSec(i));end %#ok<AGROW>
lines=[lines;"";"## CovarianceAware paired core comparisons";"";"|Payload|Reference|Metric|Delta|95% CI|Wins/Ties/Losses|Relative improvement|";"|---:|---|---|---:|---|---:|---:|"];x=Q(ismember(Q.metric,["avgCsiNmse","preLdpcBer","goodputMbps","softEvm"]),:);for i=1:height(x),lines(end+1)=sprintf('|%d|%s|%s|%+.5g|[%+.5g, %+.5g]|%d/%d/%d|%+.2f%%|',x.payloadSymbols(i),x.referenceMethod(i),x.metric(i),x.meanPairedDifference(i),x.ciLower95(i),x.ciUpper95(i),x.proposedWins(i),x.ties(i),x.referenceWins(i),x.relativeImprovementPercent(i));end %#ok<AGROW>
lines=[lines;"";"## Runtime and RLS audit";"";"|Payload|Method|Runtime s|vs Base|vs FixedR3|Accepted DA|Fallback|Mean RLS trace|";"|---:|---|---:|---:|---:|---:|---:|---:|"];for i=1:height(A),lines(end+1)=sprintf('|%d|%s|%.3f|%.2f|%.2f|%.2f|%.2f|%.5g|',A.payloadSymbols(i),A.method(i),A.meanProcessingTimeSec(i),A.relativeRuntimeVsBase(i),A.relativeRuntimeVsFixedRadius3(i),A.meanAcceptedDaCount(i),A.meanFallbackCount(i),A.meanRlsTrace(i));end;text=strjoin(lines,newline); %#ok<AGROW>
end
function text=localLatex(M,Q)
lines=["% Auto-generated offline from validation50 CSV files.";"\begin{tabular}{rrlrrrrrr}";"Payload & Method & NMSE(dB) & BER & CW pass & Goodput & EVM & SINR(dB) & Time(s) \\";"\hline"];
for i=1:height(M),lines(end+1)=sprintf('%d & %s & %.3f & %.5f & %.3f & %.3f & %.4f & %.3f & %.3f \\',M.payloadSymbols(i),M.method(i),M.avgCsiNmseDb(i),M.preLdpcBer(i),M.codewordPassRate(i),M.goodputMbps(i),M.softEvmRms(i),M.effectiveSinrDb(i),M.processingTimeSec(i));end;lines=[lines;"\end{tabular}";"";sprintf('%% Paired-comparison rows are provided in validation50_paper_table_paired.csv (%d rows).',height(Q))];text=strjoin(lines,newline); %#ok<AGROW>
end
function labels=localLabel(methods),labels=string(methods);labels=replace(labels,["BaseKalmanCausal_EP","FixedRadius3Causal_EP","CovarianceAwareLocalDAKalmanCausal_EP","OJCD_LMMSE_EP_Adapted","OracleDataAidedCausal_EP","PerfectCSI_EP"],["Base","FixedR3","CovarianceAware","OJCD","Oracle","PerfectCSI"]);end
function localWriteText(path,text),tmp=char(string(path)+".tmp");f=fopen(tmp,'w','n','UTF-8');assert(f>=0);c=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear c;[ok,msg]=movefile(tmp,path,'f');assert(ok,'Atomic report write failed: %s',msg);end
